def factorial(n):
    """Calculates the factorial of a non-negative integer.
    Returns the factorial value or None for invalid input."""
    if not isinstance(n, int) or n < 0:
        return None
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

